  "دو":{faMeaning:"عددِ پس از یک و پیش از سه؛ نشان‌دهندهٔ دو فرد یا چیز.",faSynonyms:["۲"],enMeaning:"The number after one and before three; representing two items.",enSynonyms:["two","a pair"],arMeaning:"العدد الذي يلي الواحد ويسبق الثلاثة.",arSynonyms:["اثنان","اثنتان","٢"]},
  "سه":{faMeaning:"عددِ پس از دو و پیش از چهار.",faSynonyms:["۳"],enMeaning:"The number after two and before four.",enSynonyms:["three","a trio"],arMeaning:"العدد الذي يلي الاثنين ويسبق الأربعة.",arSynonyms:["ثلاثة","ثلاث","٣"]},
  "چهار":{faMeaning:"عددِ پس از سه و پیش از پنج.",faSynonyms:["۴"],enMeaning:"The number after three and before five.",enSynonyms:["four"],arMeaning:"العدد الذي يلي الثلاثة ويسبق الخمسة.",arSynonyms:["أربعة","٤"]},
  "پنج":{faMeaning:"عددِ پس از چهار و پیش از شش.",faSynonyms:["۵"],enMeaning:"The number after four and before six.",enSynonyms:["five"],arMeaning:"العدد الذي يلي الأربعة ويسبق الستة.",arSynonyms:["خمسة","٥"]},
