  "نه":{faMeaning:"عددِ پس از هشت و پیش از ده.",faSynonyms:["۹"],enMeaning:"The number after eight and before ten.",enSynonyms:["nine"],arMeaning:"العدد الذي يلي الثمانية ويسبق العشرة.",arSynonyms:["تسعة","٩"]},
