  "آدرس دادن":{faMeaning:"گفتن یا نوشتن نشانی یک مکان برای کمک به دیگری تا آن را پیدا کند؛ گاهی شامل راهنمایی مسیر نیز می‌شود.",faSynonyms:["نشانی دادن","راهنمایی مسیر"],enMeaning:"To provide a place's address or tell someone how to find it.",enSynonyms:["give an address","give directions"],arMeaning:"ذكر عنوان المكان أو إرشاد شخصٍ إلى كيفية الوصول إليه.",arSynonyms:["أعطى العنوان","أرشد إلى الطريق"]},
  "رفتن":{faMeaning:"حرکت کردن از جایی به جای دیگر یا ترک کردن محل فعلی به قصدی مشخص.",faSynonyms:["حرکت کردن","عازم شدن (بسته به بافت)"],enMeaning:"To move from one place to another or leave a place for a destination.",enSynonyms:["go","leave","travel"],arMeaning:"الانتقال من مكانٍ إلى آخر أو مغادرة مكانٍ بقصد الوصول إلى وجهة.",arSynonyms:["ذهب","انتقل","غادر"]},
  "یاد گرفتن":{faMeaning:"به دست آوردن دانش، مهارت یا توانایی از راه آموزش، تمرین یا تجربه.",faSynonyms:["آموختن","فراگرفتن"],enMeaning:"To gain knowledge or a skill through teaching, practice, or experience.",enSynonyms:["learn","acquire","pick up"],arMeaning:"اكتساب معرفةٍ أو مهارةٍ عن طريق التعليم أو التدريب أو التجربة.",arSynonyms:["تعلّم","اكتسب"]},
