  "دعوت کردن":{faMeaning:"از کسی خواستن که در دیدار، مهمانی، مراسم یا فعالیتی شرکت کند.",faSynonyms:["دعوت به عمل آوردن","فراخواندن"],enMeaning:"To ask someone to attend an event, visit, or take part in an activity.",enSynonyms:["invite","ask over","request someone's presence"],arMeaning:"طلب حضور شخصٍ في لقاءٍ أو مناسبةٍ أو دعوته للمشاركة في نشاط.",arSynonyms:["دعا","وجّه دعوة","استضاف"]},
  "پیاده‌روی کردن":{faMeaning:"برای ورزش، تفریح یا جابه‌جایی، مسافتی را با پای پیاده راه رفتن.",faSynonyms:["قدم زدن","راه رفتن"],enMeaning:"To walk, especially for exercise, leisure, or a short journey.",enSynonyms:["go for a walk","walk","take a stroll"],arMeaning:"المشي على القدمين للرياضة أو الترفيه أو الانتقال.",arSynonyms:["تمشّى","مشى"]},
  "پوشیدن":{faMeaning:"لباس یا پوشیدنی را بر تن کردن؛ همچنین در زمان‌های دیگر به معنای بر تن داشتن است.",faSynonyms:["بر تن کردن","به تن کردن"],enMeaning:"To put on or wear clothing.",enSynonyms:["wear","put on","dress in"],arMeaning:"وضع الملابس على الجسم أو ارتداؤها.",arSynonyms:["لبس","ارتدى"]},
  "اتو کردن":{faMeaning:"صاف کردن چین‌وچروک لباس یا پارچه با اتو.",faSynonyms:["اتو کشیدن","صاف کردن لباس"],enMeaning:"To remove wrinkles from clothes or fabric using an iron.",enSynonyms:["iron","press clothes"],arMeaning:"إزالة تجاعيد الملابس أو القماش باستعمال المكواة.",arSynonyms:["كوى","استخدم المكواة"]},
