  "خرد کردن":{faMeaning:"تبدیل کردن چیزی به قطعه‌های کوچک‌تر با چاقو یا ابزار دیگر.",faSynonyms:["ریز کردن","قطعه‌قطعه کردن"],enMeaning:"To cut or break something into smaller pieces.",enSynonyms:["chop","mince","cut up"],arMeaning:"تقطيع الشيء إلى قطعٍ أصغر باستعمال سكين أو أداة أخرى.",arSynonyms:["قطّع","فرم"]},
  "هم زدن":{faMeaning:"حرکت دادن پیوستهٔ مواد با قاشق یا ابزار دیگر برای ترکیب یا یکنواخت کردن آنها.",faSynonyms:["مخلوط کردن با حرکت","به‌هم زدن"],enMeaning:"To move ingredients around with a spoon or tool so they combine or become even.",enSynonyms:["stir","mix","beat (some mixtures)"],arMeaning:"تحريك المكوّنات بملعقة أو أداة حتى تمتزج أو تتجانس.",arSynonyms:["حرّك","خلط","خفق (لبعض الخلطات)"]},
  "رنده کردن":{faMeaning:"تبدیل کردن خوراکی‌هایی مانند سبزی یا پنیر به رشته‌ها یا ذرات ریز با رنده.",faSynonyms:["رنده کشیدن"],enMeaning:"To reduce food into small shreds or particles using a grater.",enSynonyms:["grate","shred"],arMeaning:"تحويل الطعام إلى خيوط أو قطعٍ صغيرة باستعمال المبشرة.",arSynonyms:["بشر","برشَم"]},
  "ساختن":{faMeaning:"به وجود آوردن یا درست کردن چیزی با کنار هم گذاشتن مواد، اجزا یا ایده‌ها.",faSynonyms:["درست کردن","ایجاد کردن","بنا کردن (برای ساختمان)"],enMeaning:"To make, create, or build something.",enSynonyms:["make","build","construct","create"],arMeaning:"إنشاء شيءٍ أو صنعه أو بناؤه بضمّ المواد أو الأجزاء.",arSynonyms:["صنع","بنى","أنشأ"]},
  "ادامه دادن":{faMeaning:"کاری یا فعالیتی را پس از شروع متوقف نکردن و آن را پیش بردن.",faSynonyms:["پیگیری کردن","دنبال کردن"],enMeaning:"To keep doing something after it has started; to carry on.",enSynonyms:["continue","keep going","carry on"],arMeaning:"مواصلة عملٍ أو نشاطٍ بعد البدء به وعدم إيقافه.",arSynonyms:["واصل","استمرّ","تابع"]},
